/**
 * @file ADR-049 Decision 5: probe the full `@jini-ai/agent-runtime` AGENT_DEFS registry.
 * Every def reports its own availability and diagnostic, preventing a picker from offering a CLI
 * whose run would fail. The host owns discovery, timeouts, caching and PATH/environment policy;
 * the transport serializes safe summaries.
 *
 * PATH probing performs filesystem I/O. Cache it across session-lifetime health polls because
 * installed CLIs do not change each turn; explicit rescan refreshes that fact.
 */
import { AGENT_DEFS, detectAgents, probeAgentModels, type DetectedAgent, runtimeSupportsExternalTools, runtimeSupportsSubagents, runtimeSupportsChromeIntegration, createNativeAgentRuntime, type NativeAgentRuntime } from "@jini-ai/agent-runtime";
import { createCliProbeCache } from "./cli-probe-cache.js";
import { MODEL_NEGATIVE_TTL_MS } from "@jini-ai/agent-runtime/model-discovery";
import type { AgentSummary } from "@jini-ai/daemon/http";

/**
 * `AgentSummary` plus one extra, Tovu-only field the shared `@jini-ai/daemon/http` wire type doesn't
 * declare — added here rather than upstream because it is a Tovu-side transport decision
 * (`assistant-transport.ts`'s prompt-assembly gate), not a `@jini-ai/daemon/http` transport concern.
 * The extra key rides the same JSON body `AgentSummary` already serializes to; a consumer that only
 * knows `AgentSummary` (e.g. `@jini-ai/chat`'s `ChatPaneAgent`) simply never reads it.
 *
 * @see {@link probeAssistantAgents} for where `carriesOwnMemory` is derived.
 */
export type AssistantAgentSummary = AgentSummary & {
  readonly discoveryPending?: boolean;
  /** Structural bridge until @jini-ai/agent-runtime publishes declarative failure hints. */
  readonly failureHints?: readonly {
    readonly category: "auth" | "unsupported-client";
    readonly patterns: readonly string[];
    readonly hint: string;
    readonly suggestedAgentId?: string;
  }[];
  /**
   * True when this def's own CLI/ACP session already carries its multi-turn conversation memory
   * across spawns — the client-safe projection of `@jini-ai/agent-runtime`'s
   * `resumesSessionViaCli`/`resumesSessionViaAcpLoad` (`types.ts`), whose own doc says a caller
   * "should skip resending the rendered transcript on follow-up turns and send just the latest user
   * message" for such a def. `apps/admin/src/lib/assistant-transport.ts`'s `startRun` reads this to
   * decide whether a turn needs the full transcript or just the newest message.
   */
  readonly carriesOwnMemory: boolean;
  /** The runtime has a native subagent tool (`@jini-ai/agent-runtime`'s `runtimeSupportsSubagents`);
   *  the admin hides the "Prefer subagents" preference for a runtime without one. */
  readonly supportsSubagents: boolean;
  /** The runtime honors Claude in Chrome (`runtimeSupportsChromeIntegration`); the admin hides the
   *  "Use Claude in Chrome" preference for a runtime without it. */
  readonly supportsClaudeInChrome: boolean;
};

/** Tovu projections and background inventory lifecycle bound to one native runtime. */
export interface AssistantAgentInventory {
  readonly runtime: NativeAgentRuntime;
  readonly listDetectedAssistantAgents: typeof listDetectedAssistantAgents;
  readonly assistantAgentDiscoveryPending: typeof assistantAgentDiscoveryPending;
  readonly listAssistantAgents: typeof listAssistantAgents;
  readonly rescanAssistantAgents: typeof rescanAssistantAgents;
  dispose(required: Record<string, never>, optional?: Record<string, never>): Promise<void>;
}

/** Defs the executor cannot drive stay out of the picker. Keep this list aligned with the
 * runtime's compatibility rules; its compatibility predicate is not publicly exported. */
const UNSUPPORTED_AGENT_IDS = new Set<string>([]);

/**
 * Test port for one available def's model list — `@jini-ai/agent-runtime`'s `probeAgentModels`, which runs
 * the def's own `fetchModels`/`listModels` (e.g. `claude`'s credential-free `initialize` probe,
 * `codex debug models`) and falls back to `fallbackModels` on any failure. Live discovery keeps
 * the Local CLI picker current. Swappable so tests never spawn real CLIs.
 */
type AgentModelProber = typeof probeAgentModels;
/** The agent-def registry an inventory projects; `AGENT_DEFS` unless a host/test injects one. A def
 * may carry the Tovu-side `failureHints` bridge (see {@link AssistantAgentSummary}). */
export type AssistantAgentDefs = readonly ((typeof AGENT_DEFS)[number] & Pick<AssistantAgentSummary, "failureHints">)[];
let agentModelProber: AgentModelProber | null = null;

/** Compatibility test wrapper: install a fake model prober (or `null` to restore the real one)
 * and replace the default inventory. Native host inventories keep their own bindings. */
export function setAgentModelProberForTesting(prober: AgentModelProber | null): void {
  agentModelProber = prober;
  defaultInventory = createAssistantAgentInventory({ runtime: createNativeAgentRuntime({ env: process.env }) });
}

/**
 * The actual probe — one PATH check per `AGENT_DEFS` entry, plus one model-listing call per
 * AVAILABLE def, plus its version/capability/auth checks. Never called directly by a route; only through
 * {@link listAssistantAgents}/{@link rescanAssistantAgents} below, which own when it re-runs.
 * `force` bypasses Jini's catalog cache on rescan; structured default evidence travels with
 * the catalog so the picker can show and dispatch the same concrete model.
 *
 * @complexity Time: O(d) in `AGENT_DEFS.length` (24 today): a PATH walk each, and for installed
 * defs read-only metadata processes bounded by each def's timeout and the shared process queue. Space: O(d).
 * @overallScore 100
 */
async function probeAssistantAgents({ force = false }: { force?: boolean } = {}, { modelProber = agentModelProber, runtime, defs = AGENT_DEFS }: { modelProber?: AgentModelProber | null; runtime: NativeAgentRuntime; defs?: AssistantAgentDefs }): Promise<DetectedAgent[]> {
  // The full detector owns version, capabilities, auth and models. Both HTTP inventories share
  // this result instead of launching a separate model-only sweep for the chat picker.
  if (!modelProber) return runtime.detectAgents({}, { force });
  const results: DetectedAgent[] = [];
  for (const def of defs.filter((candidate) => !UNSUPPORTED_AGENT_IDS.has(candidate.id))) {
    const launch = runtime.resolveAgentLaunch({ def });
    const modelResult = launch.launchPath
      ? await modelProber({ def }, { force, state: runtime.state, env: runtime.hostEnv })
      : { models: def.fallbackModels, source: "fallback" as const };
    results.push(toDetectedAgent({ def, launch, modelResult }));
  }
  return results;
}

/** One prober-path detection result: availability from the resolved launch, models from the probe.
 * Split out of {@link probeAssistantAgents} purely to keep it under the shop complexity ceiling.
 * @complexity O(1). */
function toDetectedAgent({ def, launch, modelResult }: {
  def: AssistantAgentDefs[number];
  launch: ReturnType<NativeAgentRuntime["resolveAgentLaunch"]>;
  modelResult: Awaited<ReturnType<AgentModelProber>>;
}): DetectedAgent {
  return { ...def, available: Boolean(launch.launchPath), models: modelResult.models,
    modelsSource: modelResult.source, ...(launch.selectedPath ? { path: launch.selectedPath } : {}),
    ...(modelResult.catalog ? { modelCatalog: modelResult.catalog } : {}),
    ...(modelResult.defaultModelResolution ? { defaultModelResolution: modelResult.defaultModelResolution } : {}) };
}

/** The optional def/model-derived summary fields, split out of {@link projectAssistantAgent} to keep it
 * under the shop complexity ceiling.
 * @complexity O(1). */
function optionalSummaryFields({ def, modelResult }: {
  def: AssistantAgentDefs[number];
  modelResult: Awaited<ReturnType<AgentModelProber>>;
}): Partial<AssistantAgentSummary> {
  const { failureHints } = def;
  const { catalog, defaultModelResolution } = modelResult;
  return {
    ...(failureHints ? { failureHints } : {}),
    ...(catalog ? { modelCatalog: catalog } : {}),
    ...(defaultModelResolution ? { defaultModelResolution } : {}),
    ...(def.supportsConcreteModelSelection !== undefined ? { supportsConcreteModelSelection: def.supportsConcreteModelSelection } : {}),
    ...(def.reasoningInModelId ? { reasoningInModelId: def.reasoningInModelId } : {}),
  };
}

/** The same projection serves cheap PATH-only snapshots and completed live discovery. */
function projectAssistantAgent({ def, launch, modelResult }: {
  def: AssistantAgentDefs[number];
  launch: { launchPath?: string; diagnostic?: string };
  modelResult: Awaited<ReturnType<AgentModelProber>>;
}): AssistantAgentSummary {
  const available = Boolean(launch.launchPath);
  const { models, source } = modelResult;
  return {
    id: def.id,
    name: def.name,
    available,
    supportsCustomModel: def.supportsCustomModel,
    models,
    modelsSource: source,
    ...optionalSummaryFields({ def, modelResult }),
    // See `runtimeSupportsExternalTools`'s own doc (`@jini-ai/agent-runtime`'s `registry.ts`):
    // the single derivation point for "can this runtime receive Tovu/Jini tools at all,"
    // keyed off the def's own `externalMcpInjection` declaration rather than a hardcoded
    // runtime-id list here.
    supportsTools: runtimeSupportsExternalTools({ def }),
    supportsNativeToolAccess: def.supportsNativeToolAccess === true,
    ...(def.fullCliAccessOnly ? { fullCliAccessOnly: true } : {}),
    ...(def.fullCliAccessNote ? { fullCliAccessNote: def.fullCliAccessNote } : {}),
    // See `AssistantAgentSummary.carriesOwnMemory`'s own doc — either resume mechanism means
    // the CLI itself, not this transport, owns the def's multi-turn memory.
    carriesOwnMemory: Boolean(def.resumesSessionViaCli) || Boolean(def.resumesSessionViaAcpLoad),
    supportsSubagents: runtimeSupportsSubagents({ def }),
    supportsClaudeInChrome: runtimeSupportsChromeIntegration({ def }),
    ...(def.reasoningOptions ? { reasoningOptions: def.reasoningOptions } : {}),
    ...(available ? {} : { diagnostic: launch.diagnostic ?? `${def.name} CLI not found on PATH` }),
  };
}

/** The runtime owns discovery; this host owns the shared snapshot consumed by both HTTP routes.
 * An injected detector supplies an isolated inventory for embedding hosts and route tests; injected
 * `defs` (default: the runtime's own `AGENT_DEFS`) is the registry both the cheap PATH-only snapshot
 * and the projection read from, so a host or test can supply a def shape Jini does not ship yet. */
export function createAssistantDetectionCache(
  { detector, runtime = createNativeAgentRuntime({ env: process.env }), defs = AGENT_DEFS }: { detector?: typeof detectAgents; runtime?: NativeAgentRuntime; defs?: AssistantAgentDefs },
  _options: Record<string, never> = {},
) {
  const modelProber = agentModelProber;
  const detect: typeof detectAgents = detector ?? ((_input, options = {}) => probeAssistantAgents({ ...(options.force !== undefined ? { force: options.force } : {}) }, { modelProber, runtime, defs }));
  return createCliProbeCache({
    initial: (): DetectedAgent[] => defs.filter((def) => !UNSUPPORTED_AGENT_IDS.has(def.id)).map((def) => {
      const launch = runtime.resolveAgentLaunch({ def });
      return { ...def, available: Boolean(launch.launchPath), models: def.fallbackModels.filter(model => model.id !== "default"),
        modelsSource: "fallback", ...(launch.selectedPath ? { path: launch.selectedPath } : {}) };
    }),
    probe: ({ force }) => detect({}, { force }),
  }, {
    retryAfterMs: MODEL_NEGATIVE_TTL_MS,
    // Catalogs own their retry/refresh lifetimes; executable detection stays cached in Jini.
    expiresAt: ({ snapshot }) => Math.min(Infinity, ...snapshot.flatMap(agent =>
      agent.available && agent.modelCatalog ? [Date.parse(agent.modelCatalog.expiresAt)] : [])),
  });
}
/** Tovu's picker and settings projection over one host-owned Jini runtime.
 * @param required - The runtime created by the native composition root, plus an optional detector.
 * @returns One inventory shared by both HTTP surfaces, with cleanup after background scans settle.
 * @example const inventory = createAssistantAgentInventory({ runtime });
 */
export function createAssistantAgentInventory(
  { runtime, detector, defs = AGENT_DEFS }: { runtime: NativeAgentRuntime; detector?: typeof detectAgents; defs?: AssistantAgentDefs },
  _optional: Record<string, never> = {},
): AssistantAgentInventory {
  const cachedAgents = createAssistantDetectionCache({ runtime, defs, ...(detector ? { detector } : {}) });
  let projectedSource: Promise<DetectedAgent[]> | undefined;
  let projectedPending = false;
  let projectedAgents: Promise<AssistantAgentSummary[]> | undefined;

  /** Admin detection and the chat picker read one settled inventory. No request waits for probes. */
  function listDetectedAssistantAgents({ force = false }: { force?: boolean } = {}, _options = {}): Promise<DetectedAgent[]> {
    return cachedAgents.read({ force });
  }

  function assistantAgentDiscoveryPending(_input = {}, _options = {}): boolean { return cachedAgents.isPending({}); }

  function projectDetectedAgent({ agent, discoveryPending }: { agent: DetectedAgent; discoveryPending: boolean }): AssistantAgentSummary {
    const registered = defs.find(candidate => candidate.id === agent.id)!;
    const def = { ...registered, ...(agent.reasoningOptions ? { reasoningOptions: agent.reasoningOptions } : {}) };
    return { ...projectAssistantAgent({ def, launch: { launchPath: agent.available ? agent.path : undefined }, modelResult: {
      models: agent.models, source: agent.modelsSource,
      ...(agent.modelCatalog ? { catalog: agent.modelCatalog } : {}),
      ...(agent.defaultModelResolution ? { defaultModelResolution: agent.defaultModelResolution } : {}),
    } }), discoveryPending,
      ...(agent.version ? { version: agent.version } : {}),
      ...(agent.authStatus ? { authStatus: agent.authStatus } : {}),
    };
  }

  /** Preserve promise identity until the runtime snapshot changes, including while a scan runs. */
  function listAssistantAgents(_input = {}, { waitForProbe = false } = {}): Promise<AssistantAgentSummary[]> {
    const source = listDetectedAssistantAgents();
    if (waitForProbe) return cachedAgents.settled({}).then(() => listAssistantAgents());
    const discoveryPending = cachedAgents.isPending({});
    if (source !== projectedSource || discoveryPending !== projectedPending) {
      projectedPending = discoveryPending;
      projectedSource = source;
      projectedAgents = source.then(agents => agents.map(agent => projectDetectedAgent({ agent, discoveryPending })));
    }
    return projectedAgents!;
  }

  /** Explicit Rescan schedules a forced refresh while retaining the previous inventory.
   * The optional completion port is for diagnostics/tests; HTTP never opts into waiting. */
  function rescanAssistantAgents(_input = {}, { waitForProbe = false } = {}): Promise<AssistantAgentSummary[]> {
    listDetectedAssistantAgents({ force: true });
    return waitForProbe ? cachedAgents.settled({}).then(() => listAssistantAgents()) : listAssistantAgents();
  }

  return { runtime, listDetectedAssistantAgents, assistantAgentDiscoveryPending, listAssistantAgents, rescanAssistantAgents,
    /** Dispose only after the host stops admitting requests; a pending scan finishes before cache clear. */
    async dispose(_required: Record<string, never>, _optional: Record<string, never> = {}): Promise<void> {
      await cachedAgents.settled({});
      await runtime.dispose({});
    },
  };
}

// Published process-level functions remain compatibility wrappers; native hosts create inventories.
let defaultInventory: AssistantAgentInventory | undefined;
/** Compatibility callers share a lazy process inventory; injected daemon scopes never create it. */
function processInventory(): AssistantAgentInventory {
  return defaultInventory ??= createAssistantAgentInventory({ runtime: createNativeAgentRuntime({ env: process.env }) });
}
export function listDetectedAssistantAgents(input: { force?: boolean } = {}, options = {}): Promise<DetectedAgent[]> {
  return processInventory().listDetectedAssistantAgents(input, options);
}
export function assistantAgentDiscoveryPending(input = {}, options = {}): boolean {
  return processInventory().assistantAgentDiscoveryPending(input, options);
}
export function listAssistantAgents(input = {}, options: { waitForProbe?: boolean } = {}): Promise<AssistantAgentSummary[]> {
  return processInventory().listAssistantAgents(input, options);
}
export function rescanAssistantAgents(input = {}, options: { waitForProbe?: boolean } = {}): Promise<AssistantAgentSummary[]> {
  return processInventory().rescanAssistantAgents(input, options);
}

import { randomUUID } from "node:crypto";

import type { Express, Request, Response } from "express";

import type { Principal } from "@jini-ai/core";
import type { ToolExecutionResult, ToolExecutor } from "@jini-ai/daemon";

import { RUN_PRINCIPAL_HEADER } from "./daemon-access.js";
import { isMcpUiToolCallPermitted, MCP_UI_TYPED_ANSWER_REFUSAL } from "./mcp-ui-tool-calls.js";
import { deliverSurfaceCallback } from '@jini-ai/daemon/http';
import {
  SURFACE_EXCHANGE_ID_PARAM,
  SURFACE_TYPED_ANSWER_PARAM,
  type SurfaceExchangeStore,
} from "@jini-ai/daemon/surface-exchanges";

/**
 * @file The daemon-side half of the MCP-UI callback endpoint — where a rendered surface's answer
 * re-enters the server.
 *
 * ## Two shapes, one path
 *
 * A callback arrives as either:
 *
 * 1. **An exchange delivery** (ADR-055 Decisions 1 and 2) — the body names an open
 *    {@link SurfaceExchangeStore} exchange, and therefore an agent tool call still held open and
 *    waiting. Nothing is executed: the message reaches that call, and the agent — still alive —
 *    returns the answer as its own result. This is the path a form takes, the path
 *    `content_post_delete` takes under ADR-055 Decision 2, and the path a multi-turn conversation
 *    takes for every one of its turns.
 * 2. **A legacy redemption** (ADR-053 Decision 3) — no exchange id, so the answer is a second,
 *    ordinary tool call carrying a confirmation token only the rendered dialog held. No wired tool
 *    takes this path.
 *    Left in place as generic infrastructure for a future tool that genuinely needs a second,
 *    independently-authorized call rather than a held-open one; such a tool would need its own
 *    token store alongside this branch.
 *
 * The discriminator is the exchange id's presence rather than the tool's identity, so a tool can move
 * from one shape to the other without this route learning its name.
 *
 * ## Not MCP-only, despite the path name
 *
 * Shape 1 accepts the exchange id either as a top-level `exchangeId` or inside the tool call's
 * params. The params carrier exists for MCP-UI specifically — an mcp-ui surface can only answer by
 * issuing a tool call, so its correlation has no other way home. Any channel that can name an
 * exchange directly (A2UI, the run protocol's own `surface_response`, anything later) uses the
 * top-level field and never touches the tool-call shape at all.
 *
 * ## Why an exchange delivery is not "the browser executing a tool"
 *
 * Shape 1 never calls `toolExecutor.execute`. That is the point, not an optimization: the held-open
 * call already passed the registry's authorization gate when the agent made it, and re-running the
 * gate here would authorize the human's *answer* as though it were a fresh invocation. The
 * exchange's own binding (tool + principal) is the check that belongs at this hop, and it is a
 * correctness check — a message must reach the call it answers — rather than an authorization one.
 *
 * ## Why it must live in this process
 *
 * Mounted inside `agent-daemon-server.ts` — the only process where the `ToolRegistry`/
 * `ToolExecutor`, the `SurfaceExchangeStore` every parked call (including `content_post_delete`,
 * ADR-055 Decision 2) is waiting in, and any future Shape 2 tool's own token store
 * actually live (`buildAssistantToolRegistrations` runs exactly once there, at boot). A route in
 * Tovu's own admin server cannot call `surfaceExchanges.deliver()`, `confirmations.redeem()`, or a
 * handler directly — different process, different memory — and `@jini-ai/core`'s `ToolRegistry`
 * deliberately never exposes a handler outside `ToolExecutor.execute()` even to callers inside this
 * same process (see that package's `tool-registry.ts` module doc: "the only way to actually *run* a
 * tool is through `@jini-ai/daemon`'s `ToolExecutor`"). So this route's whole job is to be the one
 * legal call site, on this process, that turns a browser-authenticated answer into either an
 * exchange delivery or `toolExecutor.execute(...)` — for Shape 2, the exact same call a model-issued
 * tool invocation makes, which is what makes THAT shape "reuse the handler" rather than "reimplement
 * its logic." Shape 1 never calls the handler a second time at all — see below.
 *
 * Covered by the daemon's existing global bearer gate (`daemon-auth.ts`'s
 * `requireAgentDaemonToken`, mounted ahead of every route in `agent-daemon-server.ts`) — this
 * module adds no exemption, so only Tovu's own proxy (`server/modules/assistant.ts`) can reach it.
 * The admin-session check that actually authenticates the human happens one hop earlier, in that
 * proxy; this route trusts the bearer gate plus {@link RUN_PRINCIPAL_HEADER} the same way every
 * other daemon route already does (`run-ownership.ts`).
 *
 * Deliberately NOT run-scoped. Unlike `/api/delegated-tool-calls`, this call carries no `runId` —
 * `@jini-ai/chat`'s `create-mcp-ui-tool-caller.ts` module doc explains why: the run that raised the
 * confirmation dialog may already have finished by the time a human clicks it, and binding
 * redemption to that run's lifetime would expire a confirmation for a reason unrelated to the
 * decision being confirmed. A fresh, single-use synthetic `RunRef` (`{id}` is `@jini-ai/core`'s
 * whole structural contract for one — see `tool-registry.ts`) satisfies `ToolExecutor.execute`'s
 * signature without asserting a real run exists.
 */

/** Mounted at the same path Tovu's proxy exposes to the browser, so `forwardToAgentDaemon`'s
 * verbatim `req.originalUrl` passthrough (`server/modules/assistant.ts`) reaches this route with no
 * separate path-rewrite to keep in sync. */
export const MCP_UI_TOOL_CALLS_PATH = "/api/admin/v1/mcp-ui/tool-calls";

export interface McpUiToolCallsRouteDeps {
  toolExecutor: ToolExecutor;
  /**
   * The SAME store `buildAssistantToolRegistrations` was given. A different instance would leave
   * every exchange unreachable — deliveries would 409 while the agent waits out its deadline.
   */
  surfaceExchanges: SurfaceExchangeStore;
}

function readPrincipalId(req: Request): string | undefined {
  const value = req.get(RUN_PRINCIPAL_HEADER);
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Maps one `ToolExecutionResult` onto an HTTP response.
 *
 * `'completed'` is the only outcome a correctly-behaving caller sees in practice: every domain tool
 * registered through `registration-kit.ts`'s `buildDomainRegistrations` carries a pass-through
 * `policy.authorize: () => "allow"` (ADR-021 §2 — the domain's OWN inline `authorize()`/
 * `requireToolPermission` call is the real gate, and it throws rather than returning a denial
 * `ToolExecutor` would see), and `requiresConfirmation` is never set on a catalog entry (see
 * `tool-registration-kit.ts`'s explanation of the missing confirmation delegate). So `'denied'`/`'confirmation-denied'` are handled for
 * completeness and to keep this switch exhaustive against `ToolExecutionStatus`, not because a live
 * path reaches them today. `'cancelled'` is similarly unreachable from this call site specifically —
 * nothing here holds the `executionId` an external `toolExecutor.cancel()` would need. `'failed'`
 * was, before ADR-055 Decision 2, `content_post_delete`'s own thrown "confirmation could not be
 * redeemed" message (a stale/reused/wrong-binding token) surfacing here as a 400. That specific call
 * site is dead now — `content_post_delete` takes Shape 1 below, whose own rejections (a stale
 * version, an expired dialog, a redelivery to an unknown-or-closed exchange) surface as this
 * function's separate 409 in the Shape 1 branch, or as an ordinary failed-tool-call result back
 * through the run that made the original call, never through THIS function. `'failed'` is kept for
 * exhaustiveness and for a future Shape 2 tool, whose thrown rejection would land here the same way.
 *
 * @complexity O(1).
 * @overallScore 100
 */
function respondToExecutionResult(res: Response, toolName: string, principalId: string, result: ToolExecutionResult): void {
  switch (result.status) {
    case "completed":
      res.status(200).json(result.output ?? {});
      return;
    case "denied":
      res.status(403).json({ error: `principal '${principalId}' is not authorized to call '${toolName}'`, code: "FORBIDDEN" });
      return;
    case "confirmation-denied":
      res.status(409).json({
        error: `'${toolName}' declined to run without a further confirmation this endpoint cannot supply`,
        code: "CONFLICT",
      });
      return;
    case "timed-out":
      res.status(504).json({ error: `'${toolName}' timed out`, code: "GATEWAY_TIMEOUT" });
      return;
    case "cancelled":
      res.status(500).json({ error: `'${toolName}' was cancelled before it completed`, code: "INTERNAL_ERROR" });
      return;
    case "failed":
      res.status(400).json({ error: result.error ?? `'${toolName}' failed`, code: "TOOL_CALL_FAILED" });
      return;
  }
}

/**
 * Registers `POST {@link MCP_UI_TOOL_CALLS_PATH}` on the daemon `app`.
 *
 * @param deps.toolExecutor - The SAME executor `agent-daemon-server.ts` built the registry with —
 * passing a different instance would mean this route executes a tool with no relationship to the
 * tool handler and its process-local state; a token-based handler would fail redemption against
 * a different store instance.
 * @complexity O(1) request handling plus the invoked tool handler's own cost.
 * @overallScore 100
 */
interface ParsedMcpUiToolCallRequest {
  readonly toolName: string;
  readonly params: Record<string, unknown>;
  /** Present only when this callback names an open exchange (Shape 1) — see this file's own
   *  "Two shapes, one path" doc. */
  readonly exchangeId: string | undefined;
}

/**
 * Validates and shapes `req`'s body, writing the 400/403 response and returning `null` on the
 * first invalid field — preserving {@link registerMcpUiToolCallsRoute}'s
 * inline validation, split out purely to keep that function's complexity under the shop ceiling.
 */
function parseMcpUiToolCallRequest(req: Request, res: Response): ParsedMcpUiToolCallRequest | null {
  const body = (req.body ?? {}) as { toolName?: unknown; params?: unknown; exchangeId?: unknown };
  const toolName = body.toolName;
  if (typeof toolName !== "string" || toolName.length === 0) {
    res.status(400).json({ error: "'toolName' must be a non-empty string", code: "VALIDATION_ERROR" });
    return null;
  }
  // The security-critical check this whole route exists to enforce — see `mcp-ui-tool-calls.ts`.
  // Checked again here even though Tovu's proxy (`server/modules/assistant.ts`) already checks it,
  // because this route — not the proxy — is the one call site that can actually reach
  // `toolExecutor.execute`. A proxy-only check would be a suggestion, not a boundary.
  const params = isPlainObject(body.params) ? body.params : {};
  // Read from a top-level `exchangeId` first, falling back to the callback param. The param is
  // MCP-UI's carrier specifically — an mcp-ui surface can only answer by issuing a tool call, so
  // its correlation has to ride inside that call's params. A channel that can name the exchange
  // directly uses the top-level field and never touches the tool-call shape at all, which is what
  // keeps this route from being MCP-only.
  const rawExchangeId = typeof body.exchangeId === "string" ? body.exchangeId : params[SURFACE_EXCHANGE_ID_PARAM];
  const exchangeId = typeof rawExchangeId === "string" && rawExchangeId.length > 0 ? rawExchangeId : undefined;
  // `isMcpUiToolCallPermitted` also admits a federated id, but ONLY as an answer to an open card
  // (G3) — so the answer shape is decided before the check, and Shape 2 can never run one.
  const typedAnswer = isTypedSurfaceAnswer(params);
  if (!isMcpUiToolCallPermitted(toolName, exchangeId !== undefined || typedAnswer, { typedAnswer })) {
    res.status(403).json({ error: typedAnswer ? MCP_UI_TYPED_ANSWER_REFUSAL : `'${toolName}' is not an MCP-UI-redeemable tool`, code: "TOOL_NOT_ALLOWLISTED" });
    return null;
  }
  return { toolName, params, exchangeId };
}

/**
 * Shape 1: an open exchange is waiting for this message. Delivers into it and writes the response.
 * Split out of {@link registerMcpUiToolCallsRoute} purely to keep that function's complexity under
 * the shop ceiling.
 */
async function deliverMcpUiExchange(
  res: Response,
  deps: Pick<McpUiToolCallsRouteDeps, "surfaceExchanges">,
  input: { exchangeId: string; params: Record<string, unknown>; toolId: string; principalId: string },
  req?: Request,
): Promise<void> {
  await deliverSurfaceCallback({
    res, store: deps.surfaceExchanges, ...input,
    admit: ({ toolId, answersAnExchange, typedAnswer }) => isMcpUiToolCallPermitted(toolId, answersAnExchange, { typedAnswer }),
  }, {
    restoreOnly: (req?.body as { restore?: unknown } | undefined)?.restore === true,
    restoreOnMiss: req !== undefined,
  });
}

/**
 * True when this callback is a human's TYPED answer — prose from the chat composer rather than a
 * click on the rendered surface. Presence of a non-blank {@link SURFACE_TYPED_ANSWER_PARAM} is the
 * whole discriminator: no form produces that param, and nothing else in the request distinguishes a
 * typed answer from a Shape-2 redemption.
 *
 * @complexity O(1).
 */
export function isTypedSurfaceAnswer(params: Record<string, unknown>): boolean {
  const raw = params[SURFACE_TYPED_ANSWER_PARAM];
  return typeof raw === "string" && raw.trim().length > 0;
}

/**
 * Shape 3: a typed answer that names no exchange. Resolves which open exchange it is for, delivers
 * it, and writes the response.
 *
 * ## Why the route resolves the correlation rather than the client
 *
 * A human typing into the composer has never seen an exchange id. The only place one exists
 * client-side is inside the surface's own HTML — which is model-influenced and rendered in a
 * sandboxed iframe, so a client that scraped an id out of it and posted it back would be supplying a
 * correlation the model wrote both ends of. `findTypedAnswerTarget` reads it off the store instead,
 * scoped to this request's server-verified principal and to the named (already allowlisted) tool.
 *
 * ## Why an unmatched typed answer must not fall through to Shape 2
 *
 * Shape 2 EXECUTES the named tool as a brand-new call. For `assistant_ask_choice` that would put a
 * second, unasked-for form on the human's screen in response to a message that was only ever meant to
 * answer the first one. A refusal is the honest outcome: there is nothing outstanding to answer.
 */
function deliverTypedSurfaceAnswer(
  res: Response,
  deps: Pick<McpUiToolCallsRouteDeps, "surfaceExchanges">,
  input: { params: Record<string, unknown>; toolId: string; principalId: string },
): void {
  const exchangeId = deps.surfaceExchanges.findTypedAnswerTarget({
    principalId: input.principalId,
    toolId: input.toolId,
  });
  if (exchangeId === undefined) {
    // Same 409 body as `deliverMcpUiExchange`'s own refusal, for the same reason: from the human's
    // side "nothing is outstanding", "it already expired" and "you have two open and named neither"
    // are one situation they cannot act on differently.
    res.status(409).json({
      error: "that dialog is no longer waiting for an answer",
      code: "SURFACE_NOT_PENDING",
      reason: "unknown-or-closed",
    });
    return;
  }
  void deliverMcpUiExchange(res, deps, { exchangeId, params: input.params, toolId: input.toolId, principalId: input.principalId });
}

/**
 * Shape 2: legacy two-call redemption (ADR-053) — executes the tool through the same
 * `ToolExecutor.execute` a model-issued call uses, and maps the outcome onto the HTTP response.
 * Split out of {@link registerMcpUiToolCallsRoute} purely to keep that function's complexity under
 * the shop ceiling.
 */
async function executeMcpUiToolCall(
  res: Response,
  deps: Pick<McpUiToolCallsRouteDeps, "toolExecutor">,
  input: { toolName: string; params: Record<string, unknown>; principalId: string },
): Promise<void> {
  const principal: Principal = { id: input.principalId };
  const run = { id: `mcp-ui-redemption:${randomUUID()}` };

  let result: ToolExecutionResult;
  try {
    result = await deps.toolExecutor.execute({ principal, run, toolId: input.toolName, input: input.params });
  } catch (error) {
    // `ToolExecutor.execute` throws only for an unregistered `toolId` (`tool-executor.ts`) — and
    // `isMcpUiToolCallAllowed` only lets through ids `buildAssistantToolRegistrations` guarantees
    // are registered (it fails the daemon's own boot otherwise), so this is unreachable in
    // practice. Reported rather than left to crash the process, in case that guarantee is ever
    // violated by a future refactor.
    const message = error instanceof Error ? error.message : String(error);
    res.status(500).json({ error: message, code: "INTERNAL_ERROR" });
    return;
  }

  respondToExecutionResult(res, input.toolName, input.principalId, result);
}

export function registerMcpUiToolCallsRoute(app: Express, deps: McpUiToolCallsRouteDeps): void {
  app.post(MCP_UI_TOOL_CALLS_PATH, async (req: Request, res: Response) => {
    const principalId = readPrincipalId(req);
    if (!principalId) {
      res.status(401).json({ error: `${RUN_PRINCIPAL_HEADER} is required`, code: "UNAUTHENTICATED" });
      return;
    }

    const parsed = parseMcpUiToolCallRequest(req, res);
    if (!parsed) return;

    // ---- Shape 1: an open exchange is waiting for this message. ----
    if (parsed.exchangeId !== undefined) {
      await deliverMcpUiExchange(res, deps, { exchangeId: parsed.exchangeId, params: parsed.params, toolId: parsed.toolName, principalId }, req);
      return;
    }

    // ---- Shape 3: a human typed their answer instead of clicking the form, so it names no
    // exchange. Checked before Shape 2 because Shape 2 would EXECUTE the tool afresh — putting a
    // second, unasked-for dialog on screen in reply to an answer to the first. ----
    if (isTypedSurfaceAnswer(parsed.params)) {
      deliverTypedSurfaceAnswer(res, deps, { params: parsed.params, toolId: parsed.toolName, principalId });
      return;
    }

    // ---- Shape 2: legacy two-call redemption (ADR-053). ----
    await executeMcpUiToolCall(res, deps, { toolName: parsed.toolName, params: parsed.params, principalId });
  });
}

import type { Tracker } from "@jini-ai/diagnostics/observability";
import { isDaemonRunId } from "#src/contracts/core/assistant-run-events";
import { createChatRunLedger as createLedger } from "@jini-ai/chat/store/runtime";
import { chatKernel, type ChatKernel } from "#src/platform/db/chat-kernel";
import type { SqliteConnectionSource } from "@jini-ai/db/kernel/sqlite";
import type { ChatRunLedger as JiniLedger, RunRef, UnlessSettled } from "@jini-ai/chat/store/runtime";
export type * from "@jini-ai/chat/store/runtime";
export { runLockKey } from "@jini-ai/chat/store/runtime";
/** Legacy host call contract while all run semantics are owned by Jini. */
export interface ChatRunLedger extends Omit<JiniLedger, "unlessSettled"> {
  unlessSettled<T>(run: RunRef, write: () => Promise<T>): Promise<UnlessSettled<T>>;
}
/** Adapt the shared run ledger and summarize only a newly committed terminal settlement.
 * Attribution lookup failure is diagnostic only and preserves the committed settlement result.
 * @complexity O(1) indexed reads/writes; event projection remains with the shared ledger.
 */
export function createChatRunLedger({ store }: { store: ChatKernel | SqliteConnectionSource }, { tracker }: { tracker?: Tracker } = {}): ChatRunLedger {
  const ledger = createLedger({ kernel: chatKernel(store), isDaemonRunId: ({ runId }) => isDaemonRunId(runId) }, {});
  return { ...ledger,
    async settle(required, optional) {
      const changed = await ledger.settle(required, optional);
      if (!changed || !tracker) return changed;
      const run = await ledger.durable?.find({ runId: required.runId }, {}).catch(() => {
        tracker.error({ error: new Error("Run analytics attribution lookup failed") }, { context: { operation: "assistant.run.product-event" } });
        return null;
      });
      if (run?.principalId) tracker.capture({ name: "assistant_run_finished", userId: run.principalId }, { properties: { chatSurface: "admin", logicalRunId: required.messageId, outcome: required.status, eventId: `assistant-finish:${required.messageId}` } });
      return changed;
    },
    unlessSettled: (run, write) => ledger.unlessSettled({ run, write }, {}) };
}

/** Separate visitor façade; no admin daemon, registry or proxy enters this composition. */
import { createFrontendControl, createFrontendGuestScope } from '@jini-ai/daemon/http';
import { PAGE_CAPABILITIES } from '@jini-ai/agentic';
import { isSameOrigin, normalizeOriginCandidate, type VerifiedOrigin } from '@jini-ai/http-kit/verified-origin';
import type { Express, Request } from 'express';
import type { Clock } from '@jini-ai/core/primitives';
import { createRateLimiter, resolveClientIp } from '#src/contracts/core/rate-limit/rate-limit';
import { allowsVisitorRequestOrigin } from './visitor-request-origin.js';
import { readVisitorPagePublication } from '#src/features/theme/visitor-publication';

export function createVisitorFrontendControl({ workspaceId, enabled, canonicalOrigin, clock }: {
  workspaceId: string; enabled: () => Promise<boolean>; canonicalOrigin: () => Promise<VerifiedOrigin>; clock: Clock;
}, _options = {}) {
  const limiter = createRateLimiter({ clock, profile: { max: 30, windowSeconds: 60, burst: 0 } });
  const scope = createFrontendGuestScope({ workspaceId, cookieName: 'tovu_visitor_frontend', cookiePath: '/api/site-assistant',
    allowsRequest: async ({ req }: { req: Request }) => {
      if (!await enabled()) return false;
      return allowsVisitorRequestOrigin({ req, method: req.method, allowsOrigin: async ({ origin }) => {
        const target = normalizeOriginCandidate({ rawUrl: origin });
        return target !== null && isSameOrigin({ target, canonical: await canonicalOrigin() });
      } });
    } });
  const resolveOwner = async ({ req }: { req: Request }) => {
    const owner = await scope.resolveOwner({ req });
    const revision = req.get('x-visitor-publication') ?? '';
    if (!owner || !readVisitorPagePublication({ revision, workspaceId })) return null;
    return { ...owner, tabId: `${owner.tabId}:${revision}` };
  };
  const control = createFrontendControl({ capabilities: PAGE_CAPABILITIES, resolveBindToken: () => undefined,
    session: { routePrefix: '/api/site-assistant/frontend-sessions', resolveOwner, maxSessions: 256, maxSessionsPerKey: 3,
      resolveCapacityKeys: ({ req, owner }) => [`ip:${resolveClientIp(req)}`, `guest:${owner!.principalId}`],
    } }, { maxOutputBytes: 24_000 });
  return { control, resolveOwner,
    async bindRequest({ req, signal, runId }: { req: Request; signal: AbortSignal; runId: string }, _optional = {}) {
      const owner = await resolveOwner({ req });
      const publication = readVisitorPagePublication({ revision: req.get('x-visitor-publication') ?? '', workspaceId });
      const unbound = { owner, publication: null, release: () => {} };
      if (!owner || !publication) return unbound;
      try {
        const release = control.bindRequest({ runId, bindToken: req.get('x-frontend-bind-token') ?? '', owner, signal });
        return { owner, publication, release };
      } catch { return unbound; }
    },
    mount({ app }: { app: Express }, _optional = {}) {
      // Both routes share per-IP and authenticated guest budgets. Minting fresh cookies/tabs
      // cannot reset the IP budget, and reconnecting releases capacity through registry detach.
      for (const path of ['credentials', 'stream']) app.use(`/api/site-assistant/frontend-sessions/${path}`, async (req, res, next) => {
        try {
          const ip = await limiter.check({ key: `ip:${resolveClientIp(req)}` });
          if (!ip.allowed) { res.sendStatus(429); return; }
          const guest = await scope.resolveGuest({ req });
          if (guest && !(await limiter.check({ key: `guest:${guest}` })).allowed) { res.sendStatus(429); return; }
          next();
        } catch { res.sendStatus(403); }
      });
      app.post('/api/site-assistant/frontend-sessions/credentials', async (req, res) => {
        try {
          const issued = await scope.issue({ req, res });
          if (!issued) { res.sendStatus(403); return; }
          res.json(issued);
        } catch { res.sendStatus(403); }
      });
      control.httpExtension({ app, context: { adapter: { env: {}, resolvedPortRef: { current: 0 },
        allowedOriginsEnvVar: 'TOVU_ALLOWED_ORIGINS', webPortEnvVar: 'PORT', bindHostEnvVar: 'HOST' } } });
    },
  };
}
